":[[\"Magendie\",\"Face postérieure du 4e ventricule\"],[\"Luschka\",\"Angles latéraux du 4e ventricule\"]]},{\"ch\":\"ch17\",\"k\":\"comparatif\",\"ti\":\"Sécrétion vs résorption du LCR\",\"p\":205,\"h\":[\"Étape\",\"Structure\"],\"r\":[[\"Sécrétion\",\"Plexus choroïdes (pie-mère invaginée dans les ventricules)\"],[\"Circulation\",\"Très lente : ventricules → espace sous-arachnoïdien\"],[\"Résorption\",\"Granulations de Pacchioni dans les sinus veineux de la dure-mère\"]]}],\"errata\":[{\"w\":\"p. 26 et 51\",\"t\":\"Le cours affirme que la substance grise est formée par les « nerfs gris » (fibres amyéliniques). En réalité, la substance grise correspond surtout aux corps cellulaires des neurones. Aucune question n'a été posée sur ce point (2 anciennes questions retirées).\"},{\"w\":\"p. 94 et 97\",\"t\":\"« Le tronc cérébral donne naissance aux 12 paires de nerfs crâniens » et « les paires I, II, III, IV naissent au niveau du 4e ventricule / aqueduc » : les nerfs I et II ne naissent pas du tronc cérébral, et le III et le IV naissent du mésencéphale (pédoncules cérébraux), étage du tronc cérébral non décrit dans le texte (alors qu'il figure sur le schéma p. 98). Aucune question posée sur ce point (1 ancienne question retirée).\"},{\"w\":\"p. 116\",\"t\":\"« Le lobe limbique ou l'insula gère la mémoire » : le lobe limbique et l'insula sont deux structures différentes (p. 113, le cours cite l'insula et le lobe du corps calleux comme lobes internes). Aucune question posée (1 ancienne question retirée).\"},{\"w\":\"p. 120\",\"t\":\"« Les ventricules cérébraux sont au nombre de trois » puis le cours en décrit quatre (3e, 4e et deux latéraux) ; le 4e ventricule appartient au tronc cérébral. Aucune question sur le nombre (1 ancienne question retirée).\"},{\"w\":\"p. 131\",\"t\":\"Le nerf pathétique (IV) innerve le muscle grand oblique de l'œil ; ce n'est pas un « muscle intervenant dans l'expression du visage » (c'est le rôle du facial VII). Aucune question posée sur cette phrase.\"},{\"w\":\"p. 130\",\"t\":\"Le chiasma optique ne se forme pas « au niveau du trou optique » mais au-dessus de la selle turcique, après le passage des nerfs dans les canaux optiques. L'ancienne question QROC a été reformulée sans cette précision.\"},{\"w\":\"p. 151\",\"t\":\"Le nerf cubital innerve les muscles de la partie INTERNE (et non externe) de l'avant-bras. Aucune question posée sur ce point.\"},{\"w\":\"p. 107\",\"t\":\"« Toutes les voies efférentes [du cervelet] sont directes, non croisées » : les voies efférentes cérébelleuses croisent en réalité (double croisement) ; la conclusion « contrôle du même côté » reste juste. L'ancienne question a été reformulée sur le contrôle homolatéral.\"},{\"w\":\"p. 207\",\"t\":\"« 2 à 10 cellules pour 10 mm³ » : l'unité est ambiguë (les valeurs usuelles sont données par mm³). Aucune question sur l'unité.\"},{\"w\":\"p. 87-88\",\"t\":\"Le réflexe médio-plantaire est cité au membre inférieur (p. 87) mais absent du tableau des niveaux radiculaires (p. 88).\"},{\"w\":\"p. 160\",\"t\":\"Plexus sacré « L5 + 3 premiers sacrés » : on décrit classiquement le tronc lombo-sacré (L4-L5) + S1-S3. La formulation du cours a été conservée telle quelle.\"},{\"w\":\"p. 168\",\"t\":\"Origine du sympathique « de C8 à L2 » : beaucoup d'ouvrages donnent D1 (T1) à L2. Valeur du cours conservée, à vérifier avec l'enseignant.\"},{\"w\":\"p. 39\",\"t\":\"La chronaxie est définie de façon simplifiée (« durée minimale de passage du courant ») ; la définition exacte est la durée nécessaire pour exciter avec une intensité égale à deux fois la rhéobase.\"},{\"w\":\"p. 15 et 42\",\"t\":\"Apparente contradiction : les dendrites « ne conduisent que dans un seul sens » (p. 15) alors que la loi de conductibilité indifférente dit qu'une fibre isolée conduit dans les deux sens (p. 42). Le sens unique in vivo est imposé par la polarisation des synapses (p. 40).\"},{\"w\":\"Coquilles\",\"t\":\"« Paccioni » pour Pacchioni (p. 205), « Vascularisade » (p. 195), « Growers » pour Gowers (p. 80), « intermediaries » (p. 75), « sensitvo-motrice » (p. 155).\"}]};\nconst IMG={\"f7\":\"@@XIMG:xxmvkq5tml_0@@\",\"m7\":\"@@XIMG:xxmvkq5tml_1@@\",\"f13\":\"@@XIMG:xxmvkq5tml_2@@\",\"m13\":\"@@XIMG:xxmvkq5tml_3@@\",\"f21\":\"@@XIMG:xxmvkq5tml_4@@\",\"m21\":\"@@XIMG:xxmvkq5tml_5@@\",\"f27\":\"@@XIMG:xxmvkq5tml_6@@\",\"m27\":\"@@XIMG:xxmvkq5tml_7@@\",\"f28\":\"@@XIMG:xxmvkq5tml_8@@\",\"m28\":\"@@XIMG:xxmvkq5tml_9@@\",\"f46\":\"@@XIMG:xxmvkq5tml_10@@\",\"m46\":\"@@XIMG:xxmvkq5tml_11@@\",\"f74\":\"@@XIMG:xxmvkq5tml_12@@\",\"m74\":\"@@XIMG:xxmvkq5tml_13@@\",\"f76\":\"@@XIMG:xxmvkq5tml_14@@\",\"m76\":\"@@XIMG:xxmvkq5tml_15@@\",\"f79\":\"@@XIMG:xxmvkq5tml_16@@\",\"m79\":\"@@XIMG:xxmvkq5tml_17@@\",\"f90\":\"@@XIMG:xxmvkq5tml_18@@\",\"m90\":\"@@XIMG:xxmvkq5tml_19@@\",\"f91\":\"@@XIMG:xxmvkq5tml_20@@\",\"m91\":\"@@XIMG:xxmvkq5tml_21@@\",\"f98\":\"@@XIMG:xxmvkq5tml_22@@\",\"m98\":\"@@XIMG:xxmvkq5tml_23@@\",\"f99\":\"@@XIMG:xxmvkq5tml_24@@\",\"m99\":\"@@XIMG:xxmvkq5tml_25@@\",\"f105\":\"@@XIMG:xxmvkq5tml_26@@\",\"m105\":\"@@XIMG:xxmvkq5tml_27@@\",\"f106\":\"@@XIMG:xxmvkq5tml_28@@\",\"m106\":\"@@XIMG:xxmvkq5tml_29@@\",\"f108\":\"@@XIMG:xxmvkq5tml_30@@\",\"m108\":\"@@XIMG:xxmvkq5tml_31@@\",\"f114\":\"@@XIMG:xxmvkq5tml_32@@\",\"f118\":\"@@XIMG:xxmvkq5tml_33@@\",\"m118\":\"@@XIMG:xxmvkq5tml_34@@\",\"f119\":\"@@XIMG:xxmvkq5tml_35@@\",\"m119\":\"@@XIMG:xxmvkq5tml_36@@\",\"f121\":\"@@XIMG:xxmvkq5tml_37@@\",\"m121\":\"@@XIMG:xxmvkq5tml_38@@\",\"f122\":\"@@XIMG:xxmvkq5tml_39@@\",\"m122\":\"@@XIMG:xxmvkq5tml_40@@\",\"f138\":\"@@XIMG:xxmvkq5tml_41@@\",\"f144\":\"@@XIMG:xxmvkq5tml_42@@\",\"m144\":\"@@XIMG:xxmvkq5tml_43@@\",\"f152\":\"@@XIMG:xxmvkq5tml_44@@\",\"f153\":\"@@XIMG:xxmvkq5tml_45@@\",\"f158\":\"@@XIMG:xxmvkq5tml_46@@\",\"f159\":\"@@XIMG:xxmvkq5tml_47@@\",\"f35\":\"@@XIMG:xxmvkq5tml_48@@\",\"f80\":\"@@XIMG:xxmvkq5tml_49@@\",\"f88\":\"@@XIMG:xxmvkq5tml_50@@\",\"f171\":\"@@XIMG:xxmvkq5tml_51@@\",\"f173\":\"@@XIMG:xxmvkq5tml_52@@\",\"m173\":\"@@XIMG:xxmvkq5tml_53@@\",\"f182\":\"@@XIMG:xxmvkq5tml_54@@\",\"f196\":\"@@XIMG:xxmvkq5tml_55@@\",\"f200\":\"@@XIMG:xxmvkq5tml_56@@\",\"f201\":\"@@XIMG:xxmvkq5tml_57@@\",\"f206\":\"@@XIMG:xxmvkq5tml_58@@\",\"annotate_neuron\":\"@@XIMG:xxmvkq5tml_59@@\",\"annotate_moelle\":\"@@XIMG:xxmvkq5tml_60@@\",\"annotate_reflexe\":\"@@XIMG:xxmvkq5tml_61@@\",\"annotate_lobes\":\"@@XIMG:xxmvkq5tml_62@@\"};\n\"use strict\";\nconst KEY='snx_infas_v1';\nconst $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];\nconst esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};\nconst dayDiff=(a,b)=>Math.round((new Date(b)-new Date(a))/864e5);\nconst shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};\nconst norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/œ/g,'oe').replace(/æ/g,'ae');\n/* ---------- data indexes ---------- */\nconst Q={};D.q.forEach(q=>Q[q.id]=q);\nconst CH={};D.chapters.forEach((c,i)=>{c.n=i+1;CH[c.id]=c});\nconst PART={};D.parts.forEach(p=>PART[p.id]=p);\nconst PAGE={};D.course.forEach(p=>PAGE[p.p]=p);\nconst QBYCH={};D.q.forEach(q=>(QBYCH[q.ch]=QBYCH[q.ch]||[]).push(q.id));\nconst PTXT={};D.course.forEach(p=>{const t=document.createElement('div');t.innerHTML=p.html||p.title||'';PTXT[p.p]=t.textContent.replace(/\\s+/g,' ').trim()});\nconst CONTENT_PAGES=D.course.filter(p=>!p.title).map(p=>p.p);\nconst TYPES={qcm:'QCM',qcmm:'QCM multiple',vf:'Vrai / Faux',qroc:'QROC',cas:'Cas clinique',sch:'Lecture de schéma'};\nconst TYPE_IC={qcm:'🔘',qcmm:'☑️',vf:'⚖️',qroc:'✍️',cas:'🏥',sch:'🖼️'};\nconst LEVELS=[[0,'Recrue'],[150,'Apprenti·e'],[400,'Étudiant·e assidu·e'],[800,'Stagiaire confirmé·e'],[1400,'Interne des neurones'],[2200,'Major de promo'],[3200,'Expert·e du SNC'],[4500,\"Légende de l'INFAS\"]];\nconst AVATARS={'Soignant·e·s':['👩‍⚕️','👨‍⚕️','🧑‍⚕️','👩🏾‍⚕️','👨🏿‍⚕️','🧑🏽‍⚕️','🤱','🩺','🚑','🏥','💁🏾‍♀️','🙋🏿‍♂️'],'Étudiants & personnages':['🧑‍🎓','👩‍🎓','👨‍🎓','👩🏾‍🎓','👨🏿‍🎓','🧑‍🏫','🦸','🦸‍♀️','🧙','🧕','🥷','🤓'],'Santé & science':['🧠','🫀','🫁','🦴','🧬','🔬','💉','💊','🩻','🧪','🦠','🩸'],'Animaux':['🦁','🐘','🦉','🐬','🦊','🐢','🐼','🦋','🐙','🐝','🐆','🦜'],'Symboles':['⭐','🔥','💡','💎','🌟','🎯','🏆','🌈','☀️','🌙','🍀','🎓']};\nconst THEMES=[\n {n:'Framboise',pri:'#E0306A',sec:'#2B2D7C',btn:'#E0306A',acc:'#FFB020',bg:'#FFF4F7'},\n {n:'Océan',pri:'#0284C7',sec:'#0F3460',btn:'#0284C7',acc:'#22D3EE',bg:'#F0F8FF'},\n {n:'Forêt',pri:'#15803D',sec:'#14532D',btn:'#16A34A',acc:'#FACC15',bg:'#F2FBF4'},\n {n:'Améthyste',pri:'#7C3AED',sec:'#3B0764',btn:'#7C3AED',acc:'#F472B6',bg:'#F7F3FF'},\n {n:'Soleil',pri:'#EA580C',sec:'#7C2D12',btn:'#EA580C',acc:'#FBBF24',bg:'#FFF8F0'},\n {n:'Nuit',pri:'#F472B6',sec:'#818CF8',btn:'#EC4899',acc:'#FBBF24',bg:'#12112A'},\n {n:'Menthe',pri:'#0D9488',sec:'#134E4A',btn:'#0D9488',acc:'#F97316',bg:'#F0FDFA'},\n {n:'Corail',pri:'#F43F5E',sec:'#1E293B',btn:'#F43F5E',acc:'#06B6D4',bg:'#FFF5F5'}];\nconst BADGES=[\n ['first','🌱','Première réponse',s=>tot(s).n>=1],['q50','🎯','50 réponses',s=>tot(s).n>=50],['q200','🚀','200 réponses',s=>tot(s).n>=200],['q500','🛰️','500 réponses',s=>tot(s).n>=500],\n ['st3','🔥','Série de 3 jours',s=>(s.streak.best||0)>=3],['st7','🌋','Série de 7 jours',s=>(s.streak.best||0)>=7],\n ['boss1','⚔️','Premier boss vaincu',s=>Object.keys(s.bosses).length>=1],['bossall','👑','Tous les boss vaincus',s=>Object.keys(s.bosses).length>=D.bosses.length],\n ['exam10','📝','Examen blanc ≥ 10/20',s=>s.hist.some(h=>h.mode==='exam'&&h.note>=10)],['exam16','🏅','Examen blanc ≥ 16/20',s=>s.hist.some(h=>h.mode==='exam'&&h.note>=16)],\n ['fc100','🃏','100 flashcards révisées',s=>(s.fcDone||0)>=100],['read50','📖','50 pages lues',s=>Object.keys(s.read).length>=50],['readall','📚','Tout le cours lu',s=>Object.keys(s.read).length>=CONTENT_PAGES.length],\n ['sch30','🖼️','30 schémas réussis',s=>(s.types.sch||{}).c>=30],['cas30','🏥','30 cas cliniques réussis',s=>(s.types.cas||{}).c>=30],['master1','🧠','Un chapitre maîtrisé à 80 %',s=>D.chapters.some(c=>chStat(c.id,s).pct>=80)],\n ['lvl5','🎖️','Niveau Interne atteint',s=>s.xp>=1400],['legend','🌠',\"Légende de l'INFAS\",s=>s.xp>=4500]];\n/* ---------- state ---------- */\nfunction fresh(){return{name:'',avatar:'🧑‍⚕️',xp:0,streak:{last:'',count:0,best:0},qs:{},types:{},hist:[],resume:null,lt:{},hl:{},read:{},bosses:{},badges:{},theme:{...THEMES[0]},hlc:['#fff176','#a5d6a7','#f8bbd0'],fcDone:0}}\nlet S;\ntry{S=Object.assign(fresh(),JSON.parse(localStorage.getItem(KEY)||'{}'))}catch(e){S=fresh()}\nlet saveT=null;\nfunction save(){clearTimeout(saveT);saveT=setTimeout(()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}},150)}\nfunction saveNow(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}}\nfunction tot(s=S){let n=0,c=0;Object.values(s.types).forEach(t=>{n+=t.n;c+=t.c});return{n,c}}\nfunction level(xp=S.xp){let i=0;LEVELS.forEach((l,k)=>{if(xp>=l[0])i=k});const nx=LEVELS[i+1];return{i,name:LEVELS[i][1],cur:LEVELS[i][0],next:nx?nx[0]:null}}\nfunction mastered(id,s=S){const r=s.qs[id];return r&&r.last===true}\nfunction chStat(ch,s=S){const ids=QBYCH[ch]||[];let seen=0,m=0;ids.forEach(id=>{const r=s.qs[id];if(r){seen++;if(r.last)m++}});return{tot:ids.length,seen,m,pct:ids.length?Math.round(100*m/ids.length):0}}\nfunction chColor(ch){const s=chStat(ch);if(!s.seen)return'';return s.pct>=80?'g':s.pct>=40?'a':'r'}\n/* ---------- theme ---------- */\nfunction lum(h){h=h.replace('#','');const r=parseInt(h.substr(0,2),16)/255,g=parseInt(h.substr(2,2),16)/255,b=parseInt(h.substr(4,2),16)/255;return .2126*r+.7152*g+.0722*b}\nfunction mix(h,w,t){h=h.replace('#','');w=w.replace('#','');const a=[0,2,4].map(i=>parseInt(h.substr(i,2),16)),b=[0,2,4].map(i=>parseInt(w.substr(i,2),16));return'#'+a.map((v,i)=>Math.round(v+(b[i]-v)*t).toString(16).padStart(2,'0')).join('')}\nfunction hexA(h,a){h=h.replace('#','');return`rgba(${parseInt(h.substr(0,2),16)},${parseInt(h.substr(2,2),16)},${parseInt(h.substr(4,2),16)},${a})`}\nfunction applyTheme(){const t=S.theme,r=document.documentElement.style,dark=lum(t.bg)<.35;\n r.setProperty('--pri',t.pri);r.setProperty('--sec',t.sec);r.setProperty('--btn',t.btn);r.setProperty('--acc',t.acc);r.setProperty('--bg',t.bg);\n r.setProperty('--card',dark?mix(t.bg,'#ffffff',.08):'#ffffff');r.setProperty('--txt',dark?'#f2f1fa':'#1d1b2f');r.setProperty('--mut',dark?'#b9b6cf':'#6b6880');\n r.setProperty('--line',dark?'rgba(255,255,255,.12)':'rgba(30,20,60,.10)');r.setProperty('--soft',hexA(t.pri,dark?.18:.09));\n S.hlc.forEach((c,i)=>r.setProperty('--h'+(i+1),c));const m=$('meta[name=theme-color]');if(m)m.content=t.pri}\n/* ---------- gamification ---------- */\nfunction toast(m){const d=document.createElement('div');d.className='toast';d.innerHTML=m;document.body.appendChild(d);setTimeout(()=>d.remove(),2600)}\nfunction touchStreak(){const t=today();if(S.streak.last===t)return;const diff=S.streak.last?dayDiff(S.streak.last,t):99;S.streak.count=diff===1?S.streak.count+1:1;S.streak.last=t;S.streak.best=Math.max(S.streak.best||0,S.streak.count)}\nfunction addXP(n){const l0=level().i;S.xp+=n;const l1=level().i;if(l1>l0)toast('🎉 Nouveau niveau : <b>'+LEVELS[l1][1]+'</b> !')}\nfunction checkBadges(){BADGES.forEach(b=>{if(!S.badges[b[0]]&&b[3](S)){S.badges[b[0]]=today();toast(b[1]+' Badge débloqué : <b>'+b[2]+'</b>')}})}\nfunction record(q,ok){const r=S.qs[q.id]||{n:0,c:0,w:0,st:0};r.n++;if(ok){r.c++;r.st=(r.st||0)+1}else{r.w++;r.st=0}r.last=ok;S.qs[q.id]=r;\n const t=S.types[q.t]||{n:0,c:0};t.n++;if(ok)t.c++;S.types[q.t]=t;touchStreak();addXP(ok?10:2);checkBadges();save()}\n/* ---------- answer checking ---------- */\nconst ART=new Set(['le','la','les','l','un','une','des','du','de','d','au','aux','et','en']);\nfunction nq(s){return norm(s).replace(/(\\d)[,](\\d)/g,'$1.$2').replace(/[^a-z0-9.]+/g,' ').split(' ').filter(w=>w&&!ART.has(w)).join(' ').replace(/\\.$/,'').trim()}\nfunction lev(a,b){const m=a.length,n=b.length;if(!m)return n;if(!n)return m;let p=Array(n+1).fill(0).map((_,i)=>i);for(let i=1;i<=m;i++){let c=[i];for(let j=1;j<=n;j++)c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));p=c}return p[n]}\nfunction qrocOK(q,v){const u=nq(v);if(!u)return false;return q.acc.some(a=>{const x=nq(a);if(!x)return false;if(u===x)return true;const tol=x.length>=10?2:x.length>=5?1:0;if(lev(u,x)<=tol)return true;if(u.length>=4&&(u.includes(x)&&x.length>=4))return true;return false})}\nfunction isOK(q,v){if(v==null)return false;switch(q.t){case'vf':return v===q.a;case'qroc':return qrocOK(q,v);default:if(Array.isArray(q.a)){const a=[...q.a].sort().join(','),b=[...v].sort().join(',');return a===b}return v===q.a}}\nfunction answerText(q){if(q.t==='vf')return q.a?'Vrai':'Faux';if(q.t==='qroc')return q.acc[0];if(Array.isArray(q.a))return q.a.map(i=>q.o[i]).join(' ; ');return q.o[q.a]}\nfunction multi(q){return Array.isArray(q.a)}\nfunction excerpt(p){const t=PTXT[p]||'';return t.length>320?t.slice(0,320)+'…':t}\nfunction nearFig(q){if(q.t==='sch'&&q.full)return D.figs.find(f=>f.id===q.full);let best=null,bd=1e9;const pr=CH[q.ch].part;D.figs.forEach(f=>{let d=Math.abs(f.p-q.p);if(f.ch!==q.ch)d+=1000;if(CH[f.ch].part!==pr)d+=5000;if(d<bd){bd=d;best=f}});return best}\n/* ---------- navigation ---------- */\nlet VIEW={v:'home',a:{}};const STACK=[];\nconst TAB={home:'home',chapters:'chapters',chapter:'chapters',revise:'revise',stats:'stats',profile:'profile'};\nfunction go(v,a={},push=true){if(push&&!(VIEW.v===v&&JSON.stringify(VIEW.a)===JSON.stringify(a)))STACK.push({...VIEW,y:scrollY});VIEW={v,a};render();scrollTo(0,0)}\nfunction back(){const p=STACK.pop();if(!p){go('home',{},false);return}VIEW={v:p.v,a:p.a};render();setTimeout(()=>scrollTo(0,p.y||0),30)}\nfunction navTo(v){STACK.length=0;go(v,{},false)}\nfunction hdr(small){return`<header class=\"hdr ${small?'small':''}\"><h1>SYSTÈME NERVEUX</h1><div class=\"sub\">Révision complète · IDE / SF · Anatomie-Physiologie</div><div class=\"sign\">Créé par Daniel Noufe · INFAS</div></header>`}\nconst FOOT=`<div class=\"foot\">🧠 Système Nerveux · Révision INFAS<br><b>Créé par Daniel Noufe · INFAS</b></div>`;\nfunction backBtn(){return`<button class=\"back\" onclick=\"back()\">← Retour</button>`}\nfunction renderNav(){const cur=TAB[VIEW.v]||'';$('#nav').innerHTML=[['home','🏠','Accueil'],['chapters','📚','Chapitres'],['revise','🎯','Réviser'],['stats','📊','Stats'],['profile','👤','Profil']].map(([k,i,l])=>`<button class=\"${cur===k?'on':''}\" onclick=\"navTo('${k}')\"><span class=\"i\">${i}</span>${l}</button>`).join('')}\nfunction render(){hideHL();const f=V[VIEW.v]||V.home;$('#app').innerHTML=f(VIEW.a)+FOOT;renderNav();(AFTER[VIEW.v]||(()=>{}))(VIEW.a)}\nconst V={},AFTER={};\n/* ---------- rings ---------- */\nfunction ring(p,size=52){const r=size/2-5,c=2*Math.PI*r;const col=p>=80?'var(--ok)':p>=40?'var(--amb)':p>0?'var(--ko)':'#c9c6d4';return`<div class=\"ring\" style=\"width:${size}px;height:${size}px\"><svg width=\"${size}\" height=\"${size}\"><circle cx=\"${size/2}\" cy=\"${size/2}\" r=\"${r}\" stroke=\"var(--line)\" stroke-width=\"6\" fill=\"none\"/><circle cx=\"${size/2}\" cy=\"${size/2}\" r=\"${r}\" stroke=\"${col}\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\" stroke-dasharray=\"${c*p/100} ${c}\"/></svg><span>${p}%</span></div>`}\n/* ---------- HOME ---------- */\nfunction curBoss(){for(let i=0;i<D.bosses.length;i++)if(!S.bosses[D.bosses[i].id])return i;return -1}\nfunction flashCount(){return D.q.length+D.gloss.length+D.nums.length}\nV.home=()=>{const L=level(),pct=L.next?Math.round(100*(S.xp-L.cur)/(L.next-L.cur)):100;const mastCh=D.chapters.filter(c=>chStat(c.id).pct>=80).length;const bi=curBoss();\n let h=hdr()+`<div class=\"card hello\"><div class=\"row\"><div class=\"ava\">${S.avatar}</div><div class=\"grow\"><div class=\"lv\">Niveau ${L.i+1} · ${esc(L.name)}</div><h3>Bonjour ${esc(S.name||'futur·e soignant·e')} !</h3><div class=\"xpbar\"><i style=\"width:${pct}%\"></i></div><div class=\"lv\" style=\"margin-top:3px\">${S.xp} XP${L.next?' · prochain niveau à '+L.next:''}</div></div></div>\n <div class=\"minis\"><div><b>${S.xp}</b>XP</div><div><b>🔥${S.streak.count||0}</b>série</div><div><b>${mastCh}/${D.chapters.length}</b>maîtrisés</div><div><b>${Object.keys(S.bosses).length}</b>boss</div></div></div>`;\n if(bi>=0){const b=D.bosses[bi];h+=`<div class=\"card boss\" onclick=\"go('campaign')\" style=\"cursor:pointer\"><div class=\"em\">${b.emoji}</div><div class=\"grow\"><div class=\"small\" style=\"opacity:.8\">Niveau ${bi+1} · Campagne</div><div style=\"font-weight:800;font-size:18px\">Affronter ${esc(b.name)}</div><div class=\"small\" style=\"opacity:.8\">${b.chs.map(c=>'Ch.'+CH[c].n).join(' · ')} — 12 questions, 70 % pour gagner</div></div><div style=\"font-size:26px\">⚔️</div></div>`}\n else h+=`<div class=\"card boss\"><div class=\"em\">🏆</div><div><b>Tous les boss sont vaincus !</b><div class=\"small\">Tu es une légende du système nerveux.</div></div></div>`;\n if(S.resume&&S.resume.ids&&S.resume.i<S.resume.ids.length)h+=`<button class=\"btn full sec\" style=\"margin:6px 0 4px;padding:15px\" onclick=\"resumeQuiz()\">▶ Reprendre le quiz (${S.resume.i+1}/${S.resume.ids.length}) · ${esc(S.resume.title)}</button>`;\n h+=`<div class=\"card\" style=\"padding:12px\"><input id=\"srch\" placeholder=\"🔎 Rechercher dans le cours, les questions, le glossaire…\" oninput=\"doSearch(this.value)\" autocomplete=\"off\"><div id=\"sres\"></div></div>`;\n h+=`<button class=\"card launch\" onclick=\"go('custom')\"><div class=\"small\" style=\"opacity:.9;font-weight:700\">🚀 LANCER LE QUIZ</div><h3>${D.q.length} questions · ${flashCount()} fiches</h3><div class=\"small\" style=\"opacity:.92\">${D.chapters.length} chapitres · ${D.figs.length} schémas · 6 types de questions</div></button>`;\n const nNew=D.q.filter(q=>!S.qs[q.id]).length;\n h+=`<button class=\"card launch\" style=\"background:linear-gradient(135deg,var(--sec),var(--pri))\" onclick=\"go('flash',{})\"><div class=\"small\" style=\"opacity:.9;font-weight:700\">🃏 LANCER LES FLASHCARDS</div><h3>${flashCount()} fiches Leitner</h3><div class=\"small\" style=\"opacity:.92\">${CARDS.filter(due).length} à réviser aujourd'hui · ${CARDS.filter(c=>!S.lt[c.id]).length} jamais vues · ou toutes les fiches</div></button>`;\n h+=`<button class=\"btn full\" style=\"padding:14px;margin:2px 0 6px\" onclick=\"startNew(20)\">🆕 Questions pas encore traitées (${nNew}) · lancer 20</button><button class=\"btn ghost full\" onclick=\"CU.sel='new';go('custom',{})\">⚙️ Choisir parmi les non traitées (chapitre, type, nombre)</button>`;\n h+=`<div class=\"h2\">📈 Progression par partie</div><div class=\"card\">`+D.parts.map(p=>{const chs=D.chapters.filter(c=>c.part===p.id);return`<div style=\"margin:6px 0 10px\"><div class=\"row\"><b class=\"grow\">${p.icon} ${p.chap} · ${esc(p.name)}</b><span class=\"small mut\">${chs.reduce((a,c)=>a+chStat(c.id).m,0)}/${chs.reduce((a,c)=>a+chStat(c.id).tot,0)}</span></div><div class=\"seg\">${chs.map(c=>`<i class=\"${chColor(c.id)}\" title=\"${esc(c.title)}\" onclick=\"go('chapter',{id:'${c.id}'})\"></i>`).join('')}</div></div>`}).join('')+`<div class=\"small mut\">Gris : non commencé · Rouge &lt; 40 % · Ambre 40-79 % · Vert ≥ 80 %</div></div>`;\n h+=`<div class=\"h2\">🧭 Rubriques</div><div class=\"tiles\">`+TILES.map(t=>`<button class=\"tile\" onclick=\"${t[2]}\"><span class=\"i\">${t[0]}</span>${t[1]}</button>`).join('')+`</div>`;return h};\nconst TILES=[['📖','Sommaire & cours',\"go('course',{})\"],['🖼️','Images & schémas',\"go('gallery',{})\"],['📋','Résumés & tableaux',\"go('summ',{})\"],['🔢','Chiffres clés',\"go('nums',{})\"],['📚','Glossaire',\"go('gloss',{})\"],['🃏','Flashcards',\"go('flash',{})\"],['📝','Examen blanc',\"startExam()\"],['❌','Mes erreurs',\"startErrors()\"],['🧠','Révision intelligente',\"startSmart()\"],['🏥','Cas cliniques',\"startType('cas')\"],['⚖️','Vrai / Faux',\"startType('vf')\"],['✍️','QROC',\"startType('qroc')\"],['🆕','Non traitées',\"startNew(20)\"],['🔍','Lecture de schémas',\"startType('sch')\"],['🎯','Quiz personnalisé',\"go('custom',{})\"],['⚔️','Campagne & boss',\"go('campaign',{})\"],['⚠️','Points à vérifier',\"go('errata',{})\"]];\n/* search */\nlet sT=null;function doSearch(v){clearTimeout(sT);sT=setTimeout(()=>{const box=$('#sres');if(!box)return;const t=norm(v.trim());if(t.length<2){box.innerHTML='';return}\n const words=t.split(/\\s+/);const hit=s=>{const n=norm(s);return words.every(w=>n.includes(w))};let h='';\n const gl=D.gloss.filter(g=>hit(g.t+' '+g.d)).slice(0,6);const cp=D.course.filter(p=>!p.title&&hit(PTXT[p.p])).slice(0,6);const qs=D.q.filter(q=>hit(q.q+' '+(q.o||[]).join(' ')+' '+(q.acc||[]).join(' ')+' '+(q.e||''))).slice(0,10);\n if(!gl.length&&!cp.length&&!qs.length)h='<div class=\"mut small mt\">Aucun résultat.</div>';\n if(gl.length)h+='<div class=\"h3\">📚 Glossaire</div>'+gl.map(g=>`<div class=\"res\" onclick=\"this.querySelector('.fiche').hidden=!this.querySelector('.fiche').hidden\"><b>${esc(g.t)}</b> <span class=\"tag\">Ch.${CH[g.ch].n}</span><div class=\"fiche\" hidden>${esc(g.d)} <span class=\"pbadge\" onclick=\"event.stopPropagation();openPage(${g.p})\">p. ${g.p}</span></div></div>`).join('');\n if(cp.length)h+='<div class=\"h3\">📖 Cours</div>'+cp.map(p=>{const n=norm(PTXT[p.p]),i=Math.max(0,n.indexOf(words[0])-40);return`<div class=\"res\" onclick=\"openPage(${p.p})\"><span class=\"pbadge\">p. ${p.p}</span> <span class=\"tag\">Ch.${CH[p.ch].n}</span><div class=\"small mt\">…${esc(PTXT[p.p].slice(i,i+140))}…</div></div>`}).join('');\n if(qs.length)h+='<div class=\"h3\">❓ Questions</div>'+qs.map(q=>`<div class=\"res\" onclick=\"this.querySelector('.fiche').hidden=!this.querySelector('.fiche').hidden\"><span class=\"tag\">${TYPE_IC[q.t]} ${TYPES[q.t]}</span><div style=\"font-weight:600;margin-top:4px\">${esc(q.q)}</div><div class=\"fiche\" hidden><div>✅ <b>${esc(answerText(q))}</b></div><div class=\"small mt\">${esc(q.e||excerpt(q.p))}</div><div class=\"mt\"><span class=\"pbadge\" onclick=\"event.stopPropagation();openPage(${q.p})\">📖 Page source p. ${q.p}</span></div></div></div>`).join('');\n box.innerHTML=h},180)}\n/* ---------- CHAPTERS ---------- */\nV.chapters=()=>{let h=hdr(1)+`<div class=\"h2\">📚 Chapitres</div>`;D.parts.forEach(p=>{h+=`<div class=\"ptitle\">${p.icon} ${p.chap} — ${esc(p.name)}</div>`;D.chapters.filter(c=>c.part===p.id).forEach(c=>{const s=chStat(c.id);h+=`<div class=\"li\" onclick=\"go('chapter',{id:'${c.id}'})\">${ring(s.pct)}<div class=\"grow\"><div style=\"font-weight:700\">${c.icon} Ch.${c.n} · ${esc(c.title)}</div><div class=\"small mut\">p. ${c.p0}–${c.p1} · ${s.tot} questions · ${s.seen} vues</div></div><span>›</span></div>`})});return h};\nV.chapter=a=>{const c=CH[a.id],s=chStat(c.id),tab=a.tab||'quiz';const T=[['quiz','🎯 Quiz'],['cours','📖 Cours'],['fiches','🃏 Fiches'],['err','❌ Erreurs'],['sch','🖼️ Schémas'],['res','📝 Résumés'],['tab','📋 Tableaux']];\n let h=hdr(1)+backBtn()+`<div class=\"card\"><div class=\"row\">${ring(s.pct,64)}<div class=\"grow\"><div class=\"small mut\">${PART[c.part].chap} · Chapitre ${c.n}</div><div style=\"font-weight:800;font-size:20px\">${c.icon} ${esc(c.title)}</div><div class=\"small mut\">Pages ${c.p0} à ${c.p1} · ${s.m}/${s.tot} maîtrisées</div></div></div></div>`;\n h+=`<div class=\"tabs\">${T.map(t=>`<button class=\"${tab===t[0]?'on':''}\" onclick=\"VIEW.a.tab='${t[0]}';render()\">${t[1]}</button>`).join('')}</div>`;\n const ids=QBYCH[c.id];\n if(tab==='quiz'){const cnt=t=>ids.filter(i=>Q[i].t===t).length;h+=`<div class=\"card\"><div class=\"h3\">Quiz du chapitre</div><div class=\"chips\">${Object.keys(TYPES).map(t=>`<span class=\"tag\">${TYPE_IC[t]} ${TYPES[t]} : ${cnt(t)}</span>`).join('')}</div><div class=\"row mt\"><button class=\"btn grow\" onclick=\"startChapter('${c.id}',20)\">▶ 20 questions</button><button class=\"btn ghost grow\" onclick=\"startChapter('${c.id}',0)\">Toutes (${ids.length})</button></div>${(()=>{const nw=ids.filter(i=>!S.qs[i]);return`<button class=\"btn sec full mt\" onclick=\"startList(shuffle(${JSON.stringify(nw).replace(/\"/g,\"'\")}),'Non traitées · Ch.${c.n}')\" ${nw.length?'':'disabled style=\"opacity:.5\"'}>🆕 Pas encore traitées (${nw.length})</button>`})()}</div>`;\n  const b=D.bosses.find(b=>b.chs.includes(c.id));if(b)h+=`<div class=\"card boss\" style=\"cursor:pointer\" onclick=\"go('campaign',{})\"><div class=\"em\">${b.emoji}</div><div><div class=\"small\" style=\"opacity:.8\">Boss de ce chapitre</div><b>${esc(b.name)}</b> ${S.bosses[b.id]?'✅ vaincu':''}</div></div>`}\n if(tab==='cours'){h+=`<button class=\"btn full\" onclick=\"go('course',{ch:'${c.id}'})\">📖 Lire le cours du chapitre (${CONTENT_PAGES.filter(p=>PAGE[p].ch===c.id).length} pages)</button>`+D.course.filter(p=>p.ch===c.id&&!p.title).map(p=>`<div class=\"res\" onclick=\"go('course',{ch:'${c.id}',p:${p.p}})\"><span class=\"pbadge\">p. ${p.p}</span> ${S.read[p.p]?'✅':''} <span class=\"small\">${esc(PTXT[p.p].slice(0,90))}</span></div>`).join('')}\n if(tab==='fiches'){h+=`<div class=\"card\"><p>Flashcards Leitner limitées à ce chapitre : questions, glossaire et chiffres clés.</p><button class=\"btn full mt\" onclick=\"go('flash',{ch:'${c.id}'})\">🃏 Réviser les fiches du chapitre</button></div>`+D.gloss.filter(g=>g.ch===c.id).map(g=>`<div class=\"res\"><b>${esc(g.t)}</b> — <span class=\"small\">${esc(g.d)}</span></div>`).join('')}\n if(tab==='err'){const er=ids.filter(i=>S.qs[i]&&S.qs[i].last===false);h+=er.length?`<button class=\"btn full\" onclick=\"startList(${JSON.stringify(er).replace(/\"/g,\"'\")},'Erreurs · Ch.${c.n}')\">🔁 Refaire mes ${er.length} erreurs</button>`+er.map(i=>`<div class=\"res\"><div style=\"font-weight:600\">${esc(Q[i].q)}</div><div class=\"small\">✅ ${esc(answerText(Q[i]))}</div></div>`).join(''):'<div class=\"card center\">🎉 Aucune erreur enregistrée dans ce chapitre.</div>'}\n if(tab==='sch'){const fs=D.figs.filter(f=>f.ch===c.id);h+=(fs.length?`<div class=\"gal\">${fs.map(f=>`<div onclick=\"viewFig('${f.id}',${JSON.stringify(fs.map(x=>x.id)).replace(/\"/g,\"'\")})\"><img src=\"${IMG[f.id]}\" loading=\"lazy\" alt=\"\"><p>p. ${f.p} · ${esc(f.cap.slice(0,70))}…</p></div>`).join('')}</div>`:'<div class=\"card mut\">Pas de schéma dans ce chapitre.</div>')+(ids.some(i=>Q[i].t==='sch')?`<button class=\"btn full mt\" onclick=\"startList(${JSON.stringify(ids.filter(i=>Q[i].t==='sch')).replace(/\"/g,\"'\")},'Schémas · Ch.${c.n}')\">🔍 Quiz lecture de schémas</button>`:'')}\n if(tab==='res'){h+=`<div class=\"card summ\"><div class=\"h3\">🦴 Résumé d'anatomie</div>${D.anat[c.id]||''}</div><div class=\"card summ\"><div class=\"h3\">⚙️ Résumé de physiologie</div>${D.physio[c.id]||''}</div>`}\n if(tab==='tab'){h+=D.tables.filter(t=>t.ch===c.id).map(tblHTML).join('')}\n return h};\nfunction tblHTML(t){return`<div class=\"card\"><div class=\"row\"><span class=\"tag\">${t.k==='resume'?'Tableau résumé':'Comparatif'}</span><span class=\"grow\"></span><span class=\"pbadge\" onclick=\"openPage(${t.p})\">p. ${t.p}</span></div><div class=\"h3\">${esc(t.ti)}</div><div class=\"tbl\"><table><tr>${t.h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr>${t.r.map(r=>`<tr>${r.map((x,i)=>`<td>${i===0?'<b>'+esc(x)+'</b>':esc(x)}</td>`).join('')}</tr>`).join('')}</table></div></div>`}\n/* ---------- QUIZ ENGINE ---------- */\nlet SES=null;\nfunction startList(ids,title,mode='practice',extra={}){if(!ids.length){toast('Aucune question disponible pour cette sélection.');return}\n SES={ids:[...ids],i:0,ans:{},ord:{},title,mode,start:Date.now(),...extra};if(mode==='exam'){SES.end=Date.now()+40*60*1000}persistSes();go('quiz',{})}\nfunction persistSes(){if(SES&&SES.mode!=='review'){S.resume={...SES};save()}}\nfunction resumeQuiz(){if(!S.resume)return;SES={...S.resume};go('quiz',{})}\nfunction pickSmart(ids,n){const sc=id=>{const r=S.qs[id];if(!r)return 1+Math.random();if(r.last===false)return 3+r.w+Math.random();return Math.random()*.8/(1+(r.st||0))};const s=[...ids].sort((a,b)=>sc(b)-sc(a));return n?shuffle(s.slice(0,n)):shuffle(s)}\nfunction startChapter(ch,n){startList(pickSmart(QBYCH[ch],n),'Ch.'+CH[ch].n+' · '+CH[ch].title)}\nfunction startNew(n){const ids=shuffle(D.q.filter(q=>!S.qs[q.id]).map(q=>q.id));if(!ids.length){toast('🎉 Toutes les questions ont déjà été traitées !');return}startList(n?ids.slice(0,n):ids,'Questions non traitées')}\nfunction startType(t){const ids=D.q.filter(q=>q.t===t).map(q=>q.id);startList(pickSmart(ids,20),TYPES[t])}\nfunction startErrors(){const ids=D.q.filter(q=>S.qs[q.id]&&S.qs[q.id].last===false).map(q=>q.id);if(!ids.length){toast('🎉 Aucune erreur à revoir pour le moment !');return}startList(shuffle(ids).slice(0,40),'Mes erreurs')}\nfunction startSmart(){let ids=D.q.filter(q=>{const r=S.qs[q.id];return r&&(r.last===false||(r.st||0)<2)}).map(q=>q.id);ids=pickSmart(ids,20);if(ids.length<20)ids=ids.concat(shuffle(D.q.filter(q=>!S.qs[q.id]).map(q=>q.id)).slice(0,20-ids.length));startList(ids,'Révision intelligente')}\nfunction startExam(){const byCh=D.chapters.map(c=>shuffle(QBYCH[c.id]));let pick=[];const total=D.q.length;D.chapters.forEach((c,k)=>{const n=Math.max(1,Math.round(40*QBYCH[c.id].length/total));pick=pick.concat(byCh[k].slice(0,n))});pick=shuffle(pick).slice(0,40);\n if(pick.length<40){const rest=shuffle(D.q.map(q=>q.id).filter(i=>!pick.includes(i)));pick=pick.concat(rest.slice(0,40-pick.length))}startList(pick,'Examen blanc','exam')}\nfunction order(q){if(!SES.ord[q.id]){SES.ord[q.id]=q.o?shuffle(q.o.map((_,i)=>i)):[]}return SES.ord[q.id]}\nlet TIMER=null;\nV.quiz=()=>{if(!SES)return V.home();const n=SES.ids.length;if(SES.i>=n)return quizEnd();const q=Q[SES.ids[SES.i]],A=SES.ans[q.id],done=A&&A.done,exam=SES.mode==='exam',L='ABCDEFGH';\n let h=hdr(1)+`<div class=\"row\"><button class=\"back\" onclick=\"quitQuiz()\">✕ Quitter</button><span class=\"grow\"></span>${exam?`<span class=\"timer\" id=\"tmr\">40:00</span>`:''}</div>\n <div class=\"qtop\"><b>${SES.i+1}/${n}</b><div class=\"prog\"><i style=\"width:${100*(SES.i)/n}%\"></i></div></div>\n <div class=\"small\"><span class=\"tag\">${TYPE_IC[q.t]} ${TYPES[q.t]}</span><span class=\"tag\">Ch.${CH[q.ch].n}</span><span class=\"pbadge\" onclick=\"openPage(${q.p},1)\">📖 p. ${q.p}</span> <span class=\"mut\">${esc(SES.title)}</span></div>`;\n h+='<div class=\"card\">';\n if(q.t==='cas'){const m=q.q.match(/^(.*[.!»])\\s+([^.!?»]*\\?)$/s);h+=m?`<div class=\"scen\">🏥 ${esc(m[1])}</div><div class=\"qtext\">${esc(m[2])}</div>`:`<div class=\"scen\">🏥 Cas clinique</div><div class=\"qtext\">${esc(q.q)}</div>`}\n else if(q.t==='vf')h+=`<div class=\"small mut\">Vrai ou faux ?</div><div class=\"qtext\">${esc(q.q)}</div>`;\n else h+=`<div class=\"qtext\">${esc(q.q)}</div>`;\n if(q.t==='sch')h+=`<img class=\"qimg\" src=\"${IMG[q.img]}\" onclick=\"zoom('${q.img}')\" alt=\"schéma\"><div class=\"cap\">Touchez l'image pour l'agrandir.</div>`;\n if(multi(q)&&!done)h+=`<div class=\"small mut mt\">☑️ Cochez toutes les bonnes réponses.</div>`;\n if(q.t==='vf'){h+=`<div class=\"vf\">`+[[true,'✔ VRAI'],[false,'✘ FAUX']].map(([v,l])=>{let c='';if(done&&!exam){if(v===q.a)c='ok';else if(A.v===v)c='ko'}else if(A&&A.v===v)c='sel';return`<button class=\"opt ${c}\" onclick=\"ans(${v})\">${l}</button>`}).join('')+`</div>`}\n else if(q.t==='qroc'){h+=`<input id=\"qin\" placeholder=\"Votre réponse…\" value=\"${esc(A?A.v:'')}\" ${done&&!exam?'disabled':''} onkeydown=\"if(event.key==='Enter')ansQroc()\" autocomplete=\"off\" autocapitalize=\"off\">`+(done&&!exam?'':`<button class=\"btn full mt\" onclick=\"ansQroc()\">Valider</button>`)}\n else{const ord=order(q);const sel=A?A.v:(multi(q)?(SES.tmp||[]):null);\n  h+=ord.map((oi,k)=>{let c='';const chosen=multi(q)?(sel||[]).includes(oi):sel===oi;if(done&&!exam){const good=multi(q)?q.a.includes(oi):q.a===oi;if(good)c='ok';else if(chosen)c='ko'}else if(chosen)c='sel';return`<button class=\"opt ${c}\" onclick=\"${multi(q)?`tog(${oi})`:`ans(${oi})`}\"><span class=\"k\">${multi(q)?(chosen?'✓':L[k]):L[k]}</span><span>${esc(q.o[oi])}</span></button>`}).join('');\n  if(multi(q)&&!(done&&!exam))h+=`<button class=\"btn full mt\" onclick=\"ansMulti()\">Valider ma sélection</button>`}\n h+='</div>';\n if(done&&!exam)h+=feedback(q,A);\n h+=`<div class=\"row mt\">`+(SES.i>0&&exam?`<button class=\"btn ghost\" onclick=\"SES.i--;persistSes();render()\">← Préc.</button>`:'')+`<span class=\"grow\"></span>`+((done||exam)?`<button class=\"btn\" onclick=\"nextQ()\">${SES.i+1<n?'Suivante →':(exam?'Terminer l\\'examen':'Voir le résultat')}</button>`:`<button class=\"btn ghost\" onclick=\"skipQ()\">Je ne sais pas</button>`)+`</div>`;\n if(exam)h+=`<div class=\"card small mut\">📝 Examen blanc : aucune correction avant la fin. Réponses données : ${Object.keys(SES.ans).length}/${n}. <button class=\"btn sm sec\" onclick=\"finishExam()\">Terminer maintenant</button></div>`;\n return h};\nAFTER.quiz=()=>{clearInterval(TIMER);if(SES&&SES.mode==='exam'){const tick=()=>{const r=Math.max(0,SES.end-Date.now()),m=Math.floor(r/60000),s=Math.floor(r%60000/1000),el=$('#tmr');if(el)el.textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');if(r<=0){clearInterval(TIMER);toast('⏰ Temps écoulé !');finishExam()}};tick();TIMER=setInterval(tick,1000)}const qi=$('#qin');if(qi&&!qi.disabled&&matchMedia('(min-width:700px)').matches)qi.focus()};\nfunction feedback(q,A){const ok=A.ok,f=nearFig(q);let h=`<div class=\"fb ${ok?'ok':'ko'}\"><h4>${ok?'✅ Bonne réponse ! +10 XP':'❌ Pas tout à fait… +2 XP'}</h4>`;\n if(!ok||q.t==='qroc')h+=`<div>Réponse attendue : <b>${esc(answerText(q))}</b></div>`;\n const ex='<i>Extrait du cours (p. '+q.p+') :</i> « '+esc(excerpt(q.p))+' »';h+=`<div class=\"mt\">${q.e?esc(q.e):''}${!q.e||q.e.length<45?(q.e?'<div class=\"small mut mt\">':'<div>')+ex+'</div>':''}</div>`;\n if(q.m){h+=`<div class=\"mn\">💡 ${q.m.sigle?'<b>'+esc(q.m.sigle)+'</b><br>':''}${esc(q.m.enfant||'')}${q.m.reformulation?'<br><i>'+esc(q.m.reformulation)+'</i>':''}</div>`}\n h+=`<div class=\"row mt\" style=\"flex-wrap:wrap\"><button class=\"btn sm ghost\" onclick=\"openPage(${q.p},1)\">📖 Page source p. ${q.p}</button><button class=\"btn sm ghost\" onclick=\"go('course',{ch:'${q.ch}',p:${q.p}})\">Lire tout le chapitre</button></div>`;\n if(f)h+=`<div class=\"mt\"><img class=\"qimg\" src=\"${IMG[f.id]}\" onclick=\"zoom('${f.id}')\" alt=\"\"><div class=\"cap\">🖼️ ${esc(f.cap)} — <span class=\"pbadge\" onclick=\"openPage(${f.p},1)\">p. ${f.p}</span></div></div>`;\n return h+`</div>`}\nfunction setAns(v){const q=Q[SES.ids[SES.i]];if(SES.ans[q.id]&&SES.ans[q.id].done&&SES.mode!=='exam')return;const ok=isOK(q,v);\n if(SES.mode==='exam'){SES.ans[q.id]={v,ok,done:true};persistSes();render();return}\n SES.ans[q.id]={v,ok,done:true};record(q,ok);SES.tmp=null;persistSes();render();setTimeout(()=>{const fb=$('.fb');if(fb)fb.scrollIntoView({behavior:'smooth',block:'nearest'})},60)}\nfunction ans(v){setAns(v)}\nfunction tog(i){const q=Q[SES.ids[SES.i]];const A=SES.ans[q.id];if(A&&A.done&&SES.mode!=='exam')return;let t=SES.mode==='exam'&&A?[...A.v]:(SES.tmp||[]);t=t.includes(i)?t.filter(x=>x!==i):[...t,i];if(SES.mode==='exam'){SES.ans[q.id]={v:t,ok:isOK(q,t),done:true};persistSes()}else SES.tmp=t;render()}\nfunction ansMulti(){const q=Q[SES.ids[SES.i]];if(SES.mode==='exam'){nextQ();return}const t=SES.tmp||[];if(!t.length){toast('Cochez au moins une proposition.');return}setAns(t)}\nfunction ansQroc(){const v=($('#qin')||{}).value||'';if(!v.trim()){toast('Écrivez une réponse (ou « Je ne sais pas »).');return}setAns(v.trim())}\nfunction skipQ(){const q=Q[SES.ids[SES.i]];setAns(q.t==='qroc'?'':(q.t==='vf'?null:(multi(q)?[]:-1)))}\nfunction nextQ(){SES.i++;SES.tmp=null;persistSes();if(SES.i>=SES.ids.length&&SES.mode==='exam'){finishExam();return}render();scrollTo(0,0)}\nfunction quitQuiz(){clearInterval(TIMER);go('home',{},false);STACK.length=0}\nfunction finishExam(){clearInterval(TIMER);const q=SES.ids.map(i=>Q[i]);q.forEach(x=>{const A=SES.ans[x.id];record(x,!!(A&&A.ok))});SES.i=SES.ids.length;quizEndRecord();render()}\nfunction quizEndRecord(){if(SES.recorded)return;SES.recorded=true;const good=SES.ids.filter(i=>SES.ans[i]&&SES.ans[i].ok).length,n=SES.ids.length;const note=Math.round(20*good/n*10)/10;\n S.hist.unshift({d:today(),mode:SES.mode,title:SES.title,score:good,total:n,note});S.hist=S.hist.slice(0,60);\n if(SES.mode==='boss'){const b=D.bosses.find(b=>b.id===SES.boss);if(good/n>=.7&&!S.bosses[b.id]){S.bosses[b.id]=today();addXP(100);setTimeout(()=>toast('🏆 '+b.name+' vaincu ! +100 XP · Avatar légendaire '+b.avatar+' débloqué'),300)}}\n S.resume=null;checkBadges();saveNow()}\nfunction quizEnd(){quizEndRecord();const good=SES.ids.filter(i=>SES.ans[i]&&SES.ans[i].ok).length,n=SES.ids.length,note=Math.round(20*good/n*10)/10;\n let h=hdr(1)+`<div class=\"card center\"><div class=\"small mut\">${esc(SES.title)}</div>`;\n if(SES.mode==='boss'){const b=D.bosses.find(b=>b.id===SES.boss),win=good/n>=.7;h+=`<div style=\"font-size:64px\">${win?'🏆':b.emoji}</div><div class=\"h2\" style=\"justify-content:center\">${win?'Victoire !':'Le boss résiste…'}</div><div class=\"mut\">${win?esc(b.name)+' est vaincu. +100 XP et avatar légendaire '+b.avatar+' !':'Il faut 70 % (9/12). Révise et retente ta chance !'}</div>`}\n h+=`<div class=\"big\">${SES.mode==='exam'?note+'/20':good+'/'+n}</div><div class=\"mut\">${good} bonne(s) réponse(s) sur ${n} · ${Math.round(100*good/n)} %</div></div>`;\n const wrong=SES.ids.filter(i=>!(SES.ans[i]&&SES.ans[i].ok));\n h+=`<div class=\"row\">`+(wrong.length?`<button class=\"btn grow\" onclick=\"startList(${JSON.stringify(wrong).replace(/\"/g,\"'\")},'Correction des erreurs')\">🔁 Refaire mes erreurs (${wrong.length})</button>`:'')+`<button class=\"btn ghost grow\" onclick=\"navTo('home')\">Accueil</button></div>`;\n if(SES.mode==='exam'){h+=`<div class=\"h2\">📝 Correction détaillée</div>`+SES.ids.map((id,k)=>{const q=Q[id],A=SES.ans[id];let ua='—';if(A&&A.v!=null){if(q.t==='vf')ua=A.v?'Vrai':'Faux';else if(q.t==='qroc')ua=A.v||'—';else if(Array.isArray(A.v))ua=A.v.map(i=>q.o[i]).join(' ; ')||'—';else ua=q.o[A.v]||'—'}\n  return`<div class=\"card\" style=\"border-left:6px solid ${A&&A.ok?'var(--ok)':'var(--ko)'}\"><div class=\"small\"><b>${k+1}.</b> <span class=\"tag\">${TYPES[q.t]}</span><span class=\"pbadge\" onclick=\"openPage(${q.p})\">p. ${q.p}</span></div><div style=\"font-weight:700;margin:6px 0\">${esc(q.q)}</div>${q.t==='sch'?`<img class=\"qimg\" src=\"${IMG[q.img]}\" style=\"max-height:160px;object-fit:contain\">`:''}<div class=\"small\">Votre réponse : <b>${esc(ua)}</b> ${A&&A.ok?'✅':'❌'}</div><div class=\"small\">Bonne réponse : <b>${esc(answerText(q))}</b></div><div class=\"small mut mt\">${esc(q.e||excerpt(q.p))}</div></div>`}).join('')}\n return h}\n/* ---------- CAMPAIGN ---------- */\nV.campaign=()=>{let h=hdr(1)+backBtn()+`<div class=\"h2\">⚔️ Campagne & boss</div><div class=\"card small\">Chaque boss garde 1 à 3 chapitres. 12 questions, <b>70 %</b> pour gagner. Victoire : <b>+100 XP</b> et un <b>avatar légendaire</b>, et le boss suivant est débloqué.</div>`;\n D.bosses.forEach((b,i)=>{const won=S.bosses[b.id],open=i===0||S.bosses[D.bosses[i-1].id];h+=`<div class=\"li\" style=\"${open?'':'opacity:.5'}\" onclick=\"${open?`fightBoss('${b.id}')`:`toast('🔒 Bats d\\\\'abord ${esc(D.bosses[i-1].name).replace(/'/g,\"\\\\'\")}')`}\"><div style=\"font-size:40px\">${open?b.emoji:'🔒'}</div><div class=\"grow\"><div class=\"small mut\">Niveau ${i+1}</div><b>${esc(b.name)}</b><div class=\"small mut\">${esc(b.title)} · ${b.chs.map(c=>'Ch.'+CH[c].n).join(', ')}</div></div><div>${won?'✅':open?'⚔️':''}</div></div>`});return h};\nfunction fightBoss(id){const b=D.bosses.find(x=>x.id===id);let ids=[];b.chs.forEach(c=>ids=ids.concat(QBYCH[c]));startList(pickSmart(ids,12),'Boss : '+b.name,'boss',{boss:id})}\n/* ---------- CUSTOM ---------- */\nlet CU={part:'all',chs:null,types:Object.keys(TYPES),sel:'all',n:20};\nV.custom=()=>{if(!CU.chs)CU.chs=D.chapters.map(c=>c.id);const chs=D.chapters.filter(c=>CU.part==='all'||c.part===CU.part);const pool=customPool();\n let h=hdr(1)+backBtn()+`<div class=\"h2\">🎯 Quiz personnalisé</div><div class=\"card\"><div class=\"h3\">Partie</div><div class=\"chips\"><button class=\"chip ${CU.part==='all'?'on':''}\" onclick=\"cuPart('all')\">Toutes</button>${D.parts.map(p=>`<button class=\"chip ${CU.part===p.id?'on':''}\" onclick=\"cuPart('${p.id}')\">${p.icon} ${p.chap}</button>`).join('')}</div>\n <div class=\"h3\">Chapitres <button class=\"btn sm ghost\" onclick=\"cuAll()\">Tout / rien</button></div>${chs.map(c=>`<label class=\"chk\"><input type=\"checkbox\" ${CU.chs.includes(c.id)?'checked':''} onchange=\"cuCh('${c.id}',this.checked)\">Ch.${c.n} · ${esc(c.title)} <span class=\"mut small\">(${QBYCH[c.id].length})</span></label>`).join('')}\n <div class=\"h3\">Types de questions</div><div class=\"chips\">${Object.keys(TYPES).map(t=>`<button class=\"chip ${CU.types.includes(t)?'on':''}\" onclick=\"cuType('${t}')\">${TYPE_IC[t]} ${TYPES[t]}</button>`).join('')}</div>\n <div class=\"h3\">Sélection</div><div class=\"chips\">${[['all','Toutes'],['new','Pas encore traitées'],['weak','Non maîtrisées'],['err','Erreurs']].map(([k,l])=>`<button class=\"chip ${CU.sel===k?'on':''}\" onclick=\"CU.sel='${k}';render()\">${l}</button>`).join('')}</div>\n <div class=\"h3\">Nombre</div><div class=\"chips\">${[10,20,40,60,0].map(n=>`<button class=\"chip ${CU.n===n?'on':''}\" onclick=\"CU.n=${n};render()\">${n||'Toutes'}</button>`).join('')}</div>\n <div class=\"mt mut\">${pool.length} question(s) disponible(s)</div><button class=\"btn full mt\" onclick=\"cuGo()\">▶ Lancer (${CU.n?Math.min(CU.n,pool.length):pool.length})</button></div>`;return h};\nfunction customPool(){return D.q.filter(q=>(CU.part==='all'||CH[q.ch].part===CU.part)&&CU.chs.includes(q.ch)&&CU.types.includes(q.t)&&(CU.sel==='all'||(CU.sel==='new'&&!S.qs[q.id])||(CU.sel==='weak'&&!mastered(q.id))||(CU.sel==='err'&&S.qs[q.id]&&S.qs[q.id].last===false))).map(q=>q.id)}\nfunction cuPart(p){CU.part=p;CU.chs=D.chapters.filter(c=>p==='all'||c.part===p).map(c=>c.id);render()}\nfunction cuAll(){const chs=D.chapters.filter(c=>CU.part==='all'||c.part===CU.part).map(c=>c.id);CU.chs=chs.every(c=>CU.chs.includes(c))?[]:chs;render()}\nfunction cuCh(c,on){CU.chs=on?[...new Set([...CU.chs,c])]:CU.chs.filter(x=>x!==c);render()}\nfunction cuType(t){CU.types=CU.types.includes(t)?CU.types.filter(x=>x!==t):[...CU.types,t];render()}\nfunction cuGo(){const p=customPool();startList(CU.n?pickSmart(p,CU.n):shuffle(p),'Quiz personnalisé')}\n/* ---------- REVISE ---------- */\nV.revise=()=>{let h=hdr(1)+`<div class=\"h2\">🎯 Réviser</div><div class=\"tiles\">`+TILES.map(t=>`<button class=\"tile\" onclick=\"${t[2]}\"><span class=\"i\">${t[0]}</span>${t[1]}</button>`).join('')+`</div>`;\n const e=D.q.filter(q=>S.qs[q.id]&&S.qs[q.id].last===false).length;h+=`<div class=\"card mt\"><div class=\"row\"><div class=\"grow\"><b>❌ Mes erreurs</b><div class=\"small mut\">${e} question(s) ratée(s) à revoir</div></div><button class=\"btn sm\" onclick=\"startErrors()\">Revoir</button></div></div>`;\n h+=`<div class=\"card\"><div class=\"h3\">Par type de question</div>${Object.keys(TYPES).map(t=>`<div class=\"row\" style=\"padding:6px 0\"><span class=\"grow\">${TYPE_IC[t]} ${TYPES[t]} <span class=\"mut small\">(${D.q.filter(q=>q.t===t).length})</span></span><button class=\"btn sm ghost\" onclick=\"startType('${t}')\">20 questions</button></div>`).join('')}</div>`;return h};\n/* ---------- STATS ---------- */\nV.stats=()=>{const T=tot(),seen=Object.keys(S.qs).length,rate=T.n?Math.round(100*T.c/T.n):0;\n let h=hdr(1)+`<div class=\"h2\">📊 Statistiques</div><div class=\"kpis\"><div class=\"kpi\"><b>${S.xp}</b>XP · ${esc(level().name)}</div><div class=\"kpi\"><b>${rate} %</b>taux de réussite</div><div class=\"kpi\"><b>${seen}/${D.q.length}</b>questions vues</div><div class=\"kpi\"><b>🔥 ${S.streak.count||0}</b>série (record ${S.streak.best||0})</div><div class=\"kpi\"><b>${Object.keys(S.read).length}/${CONTENT_PAGES.length}</b>pages lues</div><div class=\"kpi\"><b>${S.fcDone||0}</b>flashcards révisées</div></div>`;\n h+=`<div class=\"h2\">🧠 Maîtrise par chapitre</div><div class=\"card\">${D.chapters.map(c=>{const s=chStat(c.id);return`<div onclick=\"go('chapter',{id:'${c.id}'})\" style=\"cursor:pointer\"><div class=\"row small\"><span class=\"grow\">Ch.${c.n} · ${esc(c.title)}</span><b>${s.pct} %</b></div><div class=\"bar\"><i style=\"width:${s.pct}%;background:${s.pct>=80?'var(--ok)':s.pct>=40?'var(--amb)':'var(--ko)'}\"></i></div></div>`}).join('')}</div>`;\n h+=`<div class=\"h2\">🧩 Réussite par type</div><div class=\"card\">${Object.keys(TYPES).map(t=>{const x=S.types[t]||{n:0,c:0},p=x.n?Math.round(100*x.c/x.n):0;return`<div class=\"row small\"><span class=\"grow\">${TYPE_IC[t]} ${TYPES[t]} <span class=\"mut\">(${x.c}/${x.n})</span></span><b>${p} %</b></div><div class=\"bar\"><i style=\"width:${p}%\"></i></div>`}).join('')}</div>`;\n const weak=D.chapters.map(c=>({c,s:chStat(c.id),r:(()=>{let n=0,k=0;QBYCH[c.id].forEach(i=>{const r=S.qs[i];if(r){n+=r.n;k+=r.c}});return n?k/n:1})()})).filter(x=>x.s.seen).sort((a,b)=>a.r-b.r).slice(0,5);\n h+=`<div class=\"h2\">🎯 Points faibles</div>`+(weak.length?weak.map(x=>`<div class=\"li\" onclick=\"startChapter('${x.c.id}',20)\"><div style=\"font-size:26px\">⚠️</div><div class=\"grow\"><b>Ch.${x.c.n} · ${esc(x.c.title)}</b><div class=\"small mut\">${Math.round(100*x.r)} % de réussite · toucher pour s'entraîner</div></div><span>▶</span></div>`).join(''):'<div class=\"card mut\">Réponds à quelques questions pour voir tes points faibles.</div>');\n h+=`<div class=\"h2\">🕓 Historique</div>`+(S.hist.length?`<div class=\"card\">${S.hist.slice(0,25).map(x=>`<div class=\"row small\" style=\"padding:6px 0;border-bottom:1px solid var(--line)\"><span class=\"mut\">${x.d}</span><span class=\"grow\">${esc(x.title)}</span><b>${x.mode==='exam'?x.note+'/20':x.score+'/'+x.total}</b></div>`).join('')}</div>`:'<div class=\"card mut\">Aucun quiz terminé pour le moment.</div>');return h};\n/* ---------- PROFILE ---------- */\nlet PROF=null;\nV.profile=()=>{if(!PROF)PROF={name:S.name,avatar:S.avatar};const leg=D.bosses.map(b=>({e:b.avatar,ok:!!S.bosses[b.id],b}));\n let h=hdr(1)+`<div class=\"h2\">👤 Profil</div><div class=\"card\"><div class=\"row\"><div class=\"ava\" style=\"background:var(--soft);border-color:var(--pri)\">${PROF.avatar}</div><div class=\"grow\"><input id=\"pname\" value=\"${esc(PROF.name)}\" placeholder=\"Ton prénom\" oninput=\"PROF.name=this.value\"></div></div>`;\n Object.entries(AVATARS).forEach(([cat,list],k)=>{h+=`<details ${k===0?'open':''}><summary>${cat}</summary><div class=\"avs\">${list.map(e=>`<button class=\"${PROF.avatar===e?'on':''}\" onclick=\"PROF.avatar='${e}';render()\">${e}</button>`).join('')}</div></details>`});\n h+=`<details open><summary>🌠 Légendaires à débloquer</summary><div class=\"avs\">${leg.map(x=>`<button class=\"${x.ok?'':'lock'} ${PROF.avatar===x.e?'on':''}\" onclick=\"${x.ok?`PROF.avatar='${x.e}';render()`:`toast('🔒 Bats le boss « ${esc(x.b.name).replace(/'/g,\"\\\\'\")} » pour débloquer cet avatar.')`}\">${x.e}</button>`).join('')}</div></details>`;\n h+=`<button class=\"btn full mt\" onclick=\"S.name=PROF.name.trim();S.avatar=PROF.avatar;saveNow();toast('✅ Profil enregistré')\">💾 Enregistrer</button></div>`;\n h+=`<div class=\"h2\">🏅 Badges</div><div class=\"bdg\">${BADGES.map(b=>`<div class=\"${S.badges[b[0]]?'':'off'}\"><span>${b[1]}</span>${b[2]}</div>`).join('')}</div>`;\n h+=`<div class=\"h2\">✏️ Couleurs du surligneur</div><div class=\"card\"><div class=\"small mut\">Une couleur par niveau d'importance.</div>${['Très important','Important','À retenir'].map((l,i)=>`<div class=\"pick\"><span><mark class=\"hl h${i+1}\">${l}</mark></span><input type=\"color\" value=\"${S.hlc[i]}\" oninput=\"S.hlc[${i}]=this.value;applyTheme();save()\"></div>`).join('')}</div>`;\n h+=`<div class=\"h2\">🎨 COULEURS DE L'APPLICATION</div><div class=\"card\"><div class=\"themes\">${THEMES.map((t,i)=>`<button style=\"background:linear-gradient(135deg,${t.pri},${t.sec})\" onclick=\"S.theme={...THEMES[${i}]};applyTheme();save();render()\">${t.n}</button>`).join('')}</div>\n ${[['pri','Couleur principale'],['sec','Couleur secondaire'],['btn','Boutons'],['acc','Accent'],['bg','Fond']].map(([k,l])=>`<div class=\"pick\"><span>${l}</span><input type=\"color\" value=\"${S.theme[k]}\" oninput=\"S.theme.${k}=this.value;applyTheme();save()\"></div>`).join('')}</div>`;\n h+=`<div class=\"h2\">💾 Sauvegarde</div><div class=\"card\"><div class=\"row\"><button class=\"btn grow\" onclick=\"exportJSON()\">⬇️ Exporter (JSON)</button><button class=\"btn ghost grow\" onclick=\"$('#impf').click()\">⬆️ Importer</button></div><input type=\"file\" id=\"impf\" accept=\".json,application/json\" hidden onchange=\"importFile(this)\">\n <details><summary>Copier / coller la sauvegarde (si le téléchargement ne marche pas)</summary><textarea id=\"jsonbox\" rows=\"4\" placeholder=\"Collez ici une sauvegarde puis Importer le texte\"></textarea><div class=\"row mt\"><button class=\"btn sm ghost grow\" onclick=\"$('#jsonbox').value=JSON.stringify(S);$('#jsonbox').select();try{document.execCommand('copy');toast('Copié')}catch(e){}\">Afficher / copier</button><button class=\"btn sm grow\" onclick=\"importText($('#jsonbox').value)\">Importer le texte</button></div></details>\n <button class=\"btn full mt\" style=\"background:var(--ko)\" onclick=\"resetAll()\">🗑️ Réinitialiser toute la progression</button></div>`;return h};\nfunction exportJSON(){try{const b=new Blob([JSON.stringify(S)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='progression_systeme_nerveux_'+today()+'.json';document.body.appendChild(a);a.click();a.remove();toast('✅ Fichier exporté')}catch(e){toast('Export impossible : utilisez « Copier / coller ».')}}\nfunction importText(t){try{const o=JSON.parse(t);if(typeof o!=='object'||!o)throw 0;S=Object.assign(fresh(),o);PROF=null;saveNow();applyTheme();render();toast('✅ Progression importée')}catch(e){toast('❌ Fichier invalide')}}\nfunction importFile(inp){const f=inp.files[0];if(!f)return;const r=new FileReader();r.onload=()=>importText(r.result);r.readAsText(f)}\nfunction resetAll(){if(!confirm('Effacer toute la progression (XP, réponses, flashcards, surlignages, profil) ?'))return;S=fresh();PROF=null;SES=null;saveNow();applyTheme();navTo('home');toast('Progression réinitialisée')}\n/* ---------- COURSE ---------- */\nlet ANNOT=false;\nV.course=a=>{const ch=a.ch||D.chapters[0].id,c=CH[ch];const pgs=D.course.filter(p=>p.ch===ch);const cp=pgs.filter(p=>!p.title),rd=cp.filter(p=>S.read[p.p]).length;const only=a.only;\n let h=hdr(1)+`<div class=\"sticky\"><div class=\"row\">${a.from?`<button class=\"btn sm sec\" onclick=\"returnQuiz()\">← Revenir où j'étais</button>`:backBtn()}<span class=\"grow\"></span><button class=\"btn sm ${ANNOT?'':'ghost'}\" onclick=\"ANNOT=!ANNOT;render();toast(ANNOT?'✏️ Mode annotation : sélectionnez du texte. Touchez un surlignage pour l\\\\'effacer.':'Annotation désactivée')\">✏️ Annoter${ANNOT?' (ON)':''}</button></div>`;\n if(!only)h+=`<div class=\"hscroll mt\">${D.chapters.map(x=>`<button class=\"chip ${x.id===ch?'on':''}\" onclick=\"go('course',{ch:'${x.id}'},false)\">Ch.${x.n}</button>`).join('')}</div>`;h+=`</div>`;\n if(only){const p=PAGE[only];h+=`<div class=\"card small\"><b>📖 Page source</b> — ${PART[c.part].chap} · Ch.${c.n} ${esc(c.title)}<div class=\"row mt\"><button class=\"btn sm\" onclick=\"go('course',{ch:'${ch}',p:${only},from:${a.from?1:0}},false)\">Lire tout le chapitre</button></div></div><div class=\"${ANNOT?'annot-on':''}\">${pageHTML(p,true)}</div>`;return h}\n h+=`<div class=\"card\"><div class=\"small mut\">${PART[c.part].icon} ${PART[c.part].chap} · ${esc(PART[c.part].name)}</div><div style=\"font-weight:800;font-size:20px\">${c.icon} Ch.${c.n} · ${esc(c.title)}</div><div class=\"small mut\">Pages ${c.p0}–${c.p1} · Pages lues : <b>${rd}/${cp.length}</b> (total ${Object.keys(S.read).length}/${CONTENT_PAGES.length})</div><div class=\"bar\"><i style=\"width:${cp.length?100*rd/cp.length:0}%\"></i></div>\n <details><summary>📑 Sommaire complet</summary>${D.parts.map(p=>`<div class=\"small\" style=\"margin-top:6px\"><b>${p.chap} · ${esc(p.name)}</b>${D.chapters.filter(x=>x.part===p.id).map(x=>`<div class=\"res\" onclick=\"go('course',{ch:'${x.id}'},false)\">Ch.${x.n} · ${esc(x.title)} <span class=\"mut\">p. ${x.p0}–${x.p1}</span></div>`).join('')}</div>`).join('')}</details></div>`;\n h+=`<div class=\"${ANNOT?'annot-on':''}\">`+pgs.map(p=>pageHTML(p,false,a.p)).join('')+`</div>`;\n h+=`<div class=\"card summ\"><div class=\"h3\">🦴 Résumé d'anatomie</div>${D.anat[ch]}<div class=\"h3\">⚙️ Résumé de physiologie</div>${D.physio[ch]}</div>`;\n const nx=D.chapters[c.n];h+=`<div class=\"row\">${c.n>1?`<button class=\"btn ghost grow\" onclick=\"go('course',{ch:'${D.chapters[c.n-2].id}'},false)\">← Ch.${c.n-1}</button>`:''}${nx?`<button class=\"btn grow\" onclick=\"go('course',{ch:'${nx.id}'},false)\">Ch.${nx.n} →</button>`:''}</div>`;return h};\nfunction pageHTML(p,single,focus){if(p.title)return`<div class=\"ptitle\" id=\"pg${p.p}\">${esc(p.title)} <span class=\"small\" style=\"opacity:.8\">· p. ${p.p}</span></div>`;\n const body=S.hl[p.p]||p.html||'';const f=p.fig?D.figs.find(x=>x.id===p.fig):null;\n return`<div class=\"pg ${S.read[p.p]?'read':''} ${focus===p.p||single?'focus':''}\" id=\"pg${p.p}\" data-p=\"${p.p}\"><span class=\"pb pbadge\">p. ${p.p}</span><div class=\"pg-body\" data-p=\"${p.p}\">${body}</div>${f?`<img src=\"${IMG[f.id]}\" loading=\"lazy\" onclick=\"zoom('${f.id}')\" alt=\"\"><div class=\"cap\">🖼️ ${p.dup?'Schéma répété (voir p. '+p.dup+') — ':''}${esc(f.cap)}</div>`:''}</div>`}\nAFTER.course=a=>{if(a.p&&!a.only){const el=$('#pg'+a.p);if(el)setTimeout(()=>el.scrollIntoView({block:'start'}),50)}if(a.only){S.read[a.only]=1;save()}\n const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const p=+e.target.dataset.p;if(!S.read[p]){S.read[p]=1;e.target.classList.add('read');save();checkBadges()}}}),{threshold:.55});$$('.pg').forEach(x=>io.observe(x))};\nfunction openPage(p,fromQuiz){const pg=PAGE[p];if(!pg){toast('Page non disponible');return}if(fromQuiz&&VIEW.v==='quiz'){RET={y:scrollY};go('course',{ch:pg.ch,p,only:p,from:1})}else go('course',{ch:pg.ch,p,only:p})}\nlet RET=null;\nfunction returnQuiz(){if(SES&&SES.i<=SES.ids.length){STACK.length=0;VIEW={v:'quiz',a:{}};render();setTimeout(()=>scrollTo(0,RET?RET.y:0),30)}else back()}\n/* highlighter */\nfunction hideHL(){const b=$('#hlbar');if(b)b.style.display='none'}\nfunction showHL(){const sel=getSelection();if(!ANNOT||!sel.rangeCount||sel.isCollapsed){hideHL();return}const r=sel.getRangeAt(0);const body=(r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement).closest('.pg-body');if(!body){hideHL();return}\n const rc=r.getBoundingClientRect(),b=$('#hlbar');b.innerHTML=S.hlc.map((c,i)=>`<button style=\"background:${c}\" onmousedown=\"event.preventDefault()\" ontouchstart=\"\" onclick=\"applyHL(${i+1})\"></button>`).join('')+`<button onmousedown=\"event.preventDefault()\" onclick=\"applyHL(0)\" title=\"Gomme\">🧽</button>`;\n b.style.display='flex';const top=rc.top-56<8?rc.bottom+10:rc.top-56;b.style.top=top+'px';b.style.left=Math.max(8,Math.min(innerWidth-210,rc.left+rc.width/2-100))+'px'}\ndocument.addEventListener('selectionchange',()=>{clearTimeout(window._hlT);window._hlT=setTimeout(showHL,250)});\nfunction textNodesIn(range,root){const out=[];const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(range.intersectsNode(n)&&n.nodeValue.trim())out.push(n)}return out}\nfunction applyHL(k){const sel=getSelection();if(!sel.rangeCount)return;const r=sel.getRangeAt(0);const body=(r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement).closest('.pg-body');if(!body)return;\n if(k===0){$$('mark.hl',body).forEach(m=>{if(r.intersectsNode(m))unwrap(m)})}\n else{const nodes=textNodesIn(r,body);nodes.forEach(n=>{let s=0,e=n.nodeValue.length;if(n===r.startContainer)s=r.startOffset;if(n===r.endContainer)e=r.endOffset;if(e<=s)return;const pm=n.parentElement.closest('mark.hl');let t=n;if(s>0)t=t.splitText(s);if(e-s<t.nodeValue.length)t.splitText(e-s);if(pm){pm.className='hl h'+k;return}const m=document.createElement('mark');m.className='hl h'+k;t.parentNode.insertBefore(m,t);m.appendChild(t)})}\n body.normalize();S.hl[body.dataset.p]=body.innerHTML;save();sel.removeAllRanges();hideHL()}\nfunction unwrap(m){const p=m.parentNode;while(m.firstChild)p.insertBefore(m.firstChild,m);p.removeChild(m)}\ndocument.addEventListener('click',e=>{const m=e.target.closest&&e.target.closest('mark.hl');if(m&&ANNOT&&getSelection().isCollapsed){const body=m.closest('.pg-body');unwrap(m);body.normalize();S.hl[body.dataset.p]=body.innerHTML;save();toast('Surlignage effacé')}});\n/* ---------- GALLERY ---------- */\nlet GAL={part:'all',ch:'all'};\nV.gallery=()=>{const fs=galList();let h=hdr(1)+backBtn()+`<div class=\"h2\">🖼️ Images & schémas <span class=\"badge\">${D.figs.length}</span></div><div class=\"hscroll\"><button class=\"chip ${GAL.part==='all'?'on':''}\" onclick=\"GAL={part:'all',ch:'all'};render()\">Toutes</button>${D.parts.map(p=>`<button class=\"chip ${GAL.part===p.id?'on':''}\" onclick=\"GAL={part:'${p.id}',ch:'all'};render()\">${p.icon} ${p.chap}</button>`).join('')}</div>\n <select class=\"mt\" onchange=\"GAL.ch=this.value;render()\"><option value=\"all\">Tous les chapitres</option>${D.chapters.filter(c=>GAL.part==='all'||c.part===GAL.part).map(c=>`<option value=\"${c.id}\" ${GAL.ch===c.id?'selected':''}>Ch.${c.n} · ${esc(c.title)}</option>`).join('')}</select>\n <div class=\"gal mt\">${fs.map(f=>`<div onclick=\"viewFig('${f.id}')\"><img src=\"${IMG[f.id]}\" loading=\"lazy\" alt=\"\"><p><span class=\"tag\">Ch.${CH[f.ch].n}</span>p. ${f.p}<br>${esc(f.cap.split(' :')[0].slice(0,60))}</p></div>`).join('')}</div>`;return h};\nfunction galList(){return D.figs.filter(f=>(GAL.part==='all'||CH[f.ch].part===GAL.part)&&(GAL.ch==='all'||f.ch===GAL.ch))}\nlet VW=null;\nfunction viewFig(id,list){VW={list:list||galList().map(f=>f.id),i:0};VW.i=Math.max(0,VW.list.indexOf(id));drawViewer()}\nfunction drawViewer(){$('.modal')&&$('.modal').remove();const f=D.figs.find(x=>x.id===VW.list[VW.i]);const m=document.createElement('div');m.className='modal';m.onclick=e=>{if(e.target===m)m.remove()};\n m.innerHTML=`<div class=\"box\"><div class=\"row\"><b class=\"grow\">${VW.i+1}/${VW.list.length} · Ch.${CH[f.ch].n}</b><button class=\"btn sm ghost\" onclick=\"this.closest('.modal').remove()\">✕</button></div><img class=\"mt\" src=\"${IMG[f.id]}\" alt=\"\"><div class=\"mt\">${esc(f.cap)}</div><div class=\"small mut\">${esc(CH[f.ch].title)} · page ${f.p}</div><div class=\"row mt\"><button class=\"btn sm ghost\" onclick=\"VW.i=(VW.i-1+VW.list.length)%VW.list.length;drawViewer()\">← Préc.</button><button class=\"btn sm grow\" onclick=\"this.closest('.modal').remove();openPage(${f.p})\">📖 Page source</button><button class=\"btn sm ghost\" onclick=\"VW.i=(VW.i+1)%VW.list.length;drawViewer()\">Suiv. →</button></div></div>`;document.body.appendChild(m)}\nfunction zoom(id){const m=document.createElement('div');m.className='modal';m.onclick=()=>m.remove();m.innerHTML=`<div class=\"box\" style=\"padding:6px\"><img src=\"${IMG[id]}\" alt=\"\" style=\"touch-action:pinch-zoom\"><div class=\"center small mut mt\">Touchez pour fermer</div></div>`;document.body.appendChild(m)}\n/* ---------- SUMMARIES & TABLES ---------- */\nlet SM={tab:'anat',part:'all',ch:'all'};\nV.summ=()=>{let h=hdr(1)+backBtn()+`<div class=\"h2\">📋 Résumés & tableaux</div><div class=\"tabs\">${[['anat','🦴 Résumés d\\'anatomie'],['physio','⚙️ Résumés de physiologie'],['resume','📋 Tableaux résumés'],['comparatif','⚖️ Tableaux comparatifs']].map(([k,l])=>`<button class=\"${SM.tab===k?'on':''}\" onclick=\"SM.tab='${k}';render()\">${l}</button>`).join('')}</div>\n <div class=\"hscroll mt\"><button class=\"chip ${SM.part==='all'?'on':''}\" onclick=\"SM.part='all';SM.ch='all';render()\">Tout</button>${D.parts.map(p=>`<button class=\"chip ${SM.part===p.id?'on':''}\" onclick=\"SM.part='${p.id}';SM.ch='all';render()\">${p.icon} ${p.chap}</button>`).join('')}</div>\n <select class=\"mt\" onchange=\"SM.ch=this.value;render()\"><option value=\"all\">Tous les chapitres</option>${D.chapters.filter(c=>SM.part==='all'||c.part===SM.part).map(c=>`<option value=\"${c.id}\" ${SM.ch===c.id?'selected':''}>Ch.${c.n} · ${esc(c.title)}</option>`).join('')}</select>`;\n const chs=D.chapters.filter(c=>(SM.part==='all'||c.part===SM.part)&&(SM.ch==='all'||c.id===SM.ch));\n if(SM.tab==='anat'||SM.tab==='physio')h+=chs.map(c=>`<div class=\"card summ\"><div class=\"row\"><span class=\"tag\">Ch.${c.n}</span><b class=\"grow\">${esc(c.title)}</b><span class=\"pbadge\" onclick=\"go('course',{ch:'${c.id}'})\">p. ${c.p0}</span></div>${D[SM.tab][c.id]}</div>`).join('');\n else h+=D.tables.filter(t=>t.k===SM.tab&&chs.some(c=>c.id===t.ch)).map(t=>`<div class=\"small mut\" style=\"margin:10px 4px -6px\">Ch.${CH[t.ch].n} · ${esc(CH[t.ch].title)}</div>`+tblHTML(t)).join('');\n return h};\n/* ---------- NUMS ---------- */\nlet NM={hide:false,ch:'all'};\nV.nums=()=>{const L=D.nums.filter(n=>NM.ch==='all'||n.ch===NM.ch);let h=hdr(1)+backBtn()+`<div class=\"h2\">🔢 Chiffres clés <span class=\"badge\">${D.nums.length}</span></div><div class=\"card row\"><div class=\"grow\"><b>Mode quiz</b><div class=\"small mut\">Les valeurs sont cachées : touchez pour vérifier.</div></div><button class=\"btn sm ${NM.hide?'':'ghost'}\" onclick=\"NM.hide=!NM.hide;render()\">${NM.hide?'🙈 ON':'👁️ OFF'}</button></div>\n <select onchange=\"NM.ch=this.value;render()\"><option value=\"all\">Tous les chapitres</option>${D.chapters.filter(c=>D.nums.some(n=>n.ch===c.id)).map(c=>`<option value=\"${c.id}\" ${NM.ch===c.id?'selected':''}>Ch.${c.n} · ${esc(c.title)}</option>`).join('')}</select>`;\n let last='';L.forEach(n=>{if(n.ch!==last){h+=`<div class=\"h3\" style=\"margin-top:14px\">Ch.${CH[n.ch].n} · ${esc(CH[n.ch].title)}</div>`;last=n.ch}h+=`<div class=\"num\"><div class=\"v ${NM.hide?'hid':''}\" onclick=\"this.classList.toggle('hid')\">${esc(n.v)}</div><div class=\"grow\">${esc(n.l)}</div><span class=\"pbadge\" onclick=\"openPage(${n.p})\">p. ${n.p}</span></div>`});return h};\n/* ---------- GLOSSARY ---------- */\nlet GL='';\nV.gloss=()=>{let h=hdr(1)+backBtn()+`<div class=\"h2\">📚 Glossaire <span class=\"badge\">${D.gloss.length}</span></div><input id=\"gq\" placeholder=\"🔎 Rechercher un terme…\" value=\"${esc(GL)}\" oninput=\"GL=this.value;drawGloss()\"><div id=\"gl\"></div>`;return h};\nAFTER.gloss=()=>drawGloss();\nfunction drawGloss(){const t=norm(GL.trim());const L=D.gloss.filter(g=>!t||norm(g.t+' '+g.d).includes(t)).sort((a,b)=>norm(a.t).localeCompare(norm(b.t)));let h='',lt='';L.forEach(g=>{const l=norm(g.t)[0].toUpperCase();if(l!==lt&&!t){h+=`<div class=\"h3\" style=\"color:var(--pri)\">${l}</div>`;lt=l}h+=`<div class=\"res\"><div class=\"row\"><b class=\"grow\">${esc(g.t)}</b><span class=\"tag\">Ch.${CH[g.ch].n}</span><span class=\"pbadge\" onclick=\"openPage(${g.p})\">p. ${g.p}</span></div><div class=\"small mt\">${esc(g.d)}</div></div>`});$('#gl').innerHTML=h||'<div class=\"mut mt\">Aucun terme.</div>'}\n/* ---------- FLASHCARDS (Leitner) ---------- */\nconst INTV=[0,0,1,2,4,8];\nfunction cards(){const c=[];D.q.forEach(q=>c.push({id:'q:'+q.id,ch:q.ch,src:'q',p:q.p,f:(q.t==='vf'?'Vrai ou faux ? ':'')+q.q,img:q.t==='sch'?q.img:null,b:answerText(q),e:q.e||''}));D.gloss.forEach((g,i)=>c.push({id:'g:'+i,ch:g.ch,src:'g',p:g.p,f:'📚 '+g.t,b:g.d,e:''}));D.nums.forEach((n,i)=>c.push({id:'n:'+i,ch:n.ch,src:'n',p:n.p,f:'🔢 '+n.l,b:n.v,e:''}));return c}\nconst CARDS=cards();\nlet FC={src:'all',ch:'all',deck:null,i:0,flip:false,sel:'due',n:20};\nfunction due(c){const r=S.lt[c.id];if(!r)return true;return r.d<=today()}\nV.flash=a=>{if(a.ch&&FC.ch!==a.ch&&!FC.deck){FC.ch=a.ch}const pool=CARDS.filter(c=>(FC.src==='all'||c.src===FC.src)&&(FC.ch==='all'||c.ch===FC.ch));const bx=[0,0,0,0,0];pool.forEach(c=>{const r=S.lt[c.id];bx[(r?r.b:1)-1]++});const dn=pool.filter(due).length;\n let h=hdr(1)+backBtn()+`<div class=\"h2\">🃏 Flashcards Leitner</div>`;\n if(FC.deck&&FC.i<FC.deck.length){const c=FC.deck[FC.i],r=S.lt[c.id];h+=`<div class=\"qtop\"><b>${FC.i+1}/${FC.deck.length}</b><div class=\"prog\"><i style=\"width:${100*FC.i/FC.deck.length}%\"></i></div><span class=\"tag\">Boîte ${r?r.b:1}</span></div>\n  <div class=\"fc ${FC.flip?'flip':''}\" onclick=\"FC.flip=!FC.flip;this.classList.toggle('flip')\"><div class=\"in\" style=\"min-height:${c.img?380:260}px\"><div class=\"f\"><div class=\"small\" style=\"opacity:.8\">Ch.${CH[c.ch].n} · touchez pour retourner</div><div class=\"mt\">${esc(c.f)}</div>${c.img?`<img src=\"${IMG[c.img]}\" style=\"width:100%;border-radius:12px;margin-top:8px;background:#fff\">`:''}</div><div class=\"b\"><div class=\"small mut\">Réponse</div><div style=\"font-size:20px;font-weight:800;color:var(--pri);margin:6px 0\">${esc(c.b)}</div><div class=\"small\">${esc(c.e)}</div><div class=\"mt\"><span class=\"pbadge\" onclick=\"event.stopPropagation();openPage(${c.p})\">📖 p. ${c.p}</span></div></div></div></div>\n  <div class=\"row\"><button class=\"btn grow\" style=\"background:var(--ko)\" onclick=\"fcAns(false)\">😕 À revoir</button><button class=\"btn grow\" style=\"background:var(--ok)\" onclick=\"fcAns(true)\">😎 Je savais</button></div><button class=\"btn ghost full mt\" onclick=\"FC.deck=null;render()\">Arrêter la session</button>`;return h}\n if(FC.deck){h+=`<div class=\"card center\"><div style=\"font-size:50px\">🎉</div><b>Session terminée !</b><div class=\"mut\">${FC.deck.length} cartes révisées.</div></div>`;FC.deck=null}\n h+=`<div class=\"boxes\">${bx.map((n,i)=>`<div><b>${n}</b>Boîte ${i+1}<div class=\"mut\" style=\"font-size:10px\">${['chaque jour','2 jours','4 jours','8 jours','16 jours'][i]}</div></div>`).join('')}</div>\n <div class=\"card\"><div class=\"h3\">Source</div><div class=\"chips\">${[['all','Tout'],['q','Questions'],['g','Glossaire'],['n','Chiffres']].map(([k,l])=>`<button class=\"chip ${FC.src===k?'on':''}\" onclick=\"FC.src='${k}';render()\">${l}</button>`).join('')}</div><div class=\"h3\">Chapitre</div><select onchange=\"FC.ch=this.value;render()\"><option value=\"all\">Tous les chapitres</option>${D.chapters.map(c=>`<option value=\"${c.id}\" ${FC.ch===c.id?'selected':''}>Ch.${c.n} · ${esc(c.title)}</option>`).join('')}</select>\n <div class=\"h3\">Cartes</div><div class=\"chips\">${[['due',\"À réviser aujourd'hui (\"+dn+')'],['all','Toutes les fiches ('+pool.length+')'],['new','Jamais vues ('+pool.filter(c=>!S.lt[c.id]).length+')']].map(([k,l])=>`<button class=\"chip ${FC.sel===k?'on':''}\" onclick=\"FC.sel='${k}';render()\">${l}</button>`).join('')}</div>\n <div class=\"h3\">Nombre</div><div class=\"chips\">${[20,50,100,0].map(n=>`<button class=\"chip ${FC.n===n?'on':''}\" onclick=\"FC.n=${n};render()\">${n||'Toutes'}</button>`).join('')}</div>\n <button class=\"btn full mt\" onclick=\"fcStart()\">▶ Lancer les flashcards (${(()=>{const k=FC.sel==='all'?pool.length:FC.sel==='new'?pool.filter(c=>!S.lt[c.id]).length:dn;return FC.n?Math.min(FC.n,k):k})()})</button></div>\n <div class=\"card small mut\">Système de Leitner : une carte sue monte d'une boîte et revient de plus en plus tard ; une carte ratée retourne en boîte 1.</div>`;return h};\nfunction fcStart(){const pool=CARDS.filter(c=>(FC.src==='all'||c.src===FC.src)&&(FC.ch==='all'||c.ch===FC.ch));let d;\n if(FC.sel==='all')d=shuffle(pool);else if(FC.sel==='new')d=shuffle(pool.filter(c=>!S.lt[c.id]));else{d=pool.filter(due);d.sort((a,b)=>((S.lt[a.id]||{b:0}).b-(S.lt[b.id]||{b:0}).b)||Math.random()-.5)}\n if(!d.length){toast('Aucune carte dans cette sélection — toutes les fiches proposées.');d=shuffle(pool)}FC.deck=shuffle(FC.n?d.slice(0,FC.n):d);FC.i=0;FC.flip=false;render()}\nfunction fcAns(ok){const c=FC.deck[FC.i],r=S.lt[c.id]||{b:1};r.b=ok?Math.min(5,r.b+1):1;const d=new Date();d.setDate(d.getDate()+INTV[r.b]+(ok?0:0));r.d=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');S.lt[c.id]=r;S.fcDone=(S.fcDone||0)+1;touchStreak();addXP(ok?2:1);checkBadges();save();FC.i++;FC.flip=false;render()}\n/* ---------- ERRATA ---------- */\nV.errata=()=>hdr(1)+backBtn()+`<div class=\"h2\">⚠️ Points à vérifier dans le cours</div><div class=\"card small\">Erreurs, imprécisions ou incohérences repérées dans le PDF. Aucune question de l'application ne porte sur un point douteux.</div>`+D.errata.map(e=>`<div class=\"card\"><span class=\"pbadge\">${esc(e.w)}</span><div class=\"mt\">${esc(e.t)}</div></div>`).join('');\n/* ---------- boot ---------- */\napplyTheme();render();\n<%/script>\n</body>\n</html>\n";
